import java.util.*;

public class Test {
    int r, c;
    long[][] C = new long[64][64];
    long[][] prod = new long[64][64];
    long[][] addY = new long[64][64];
    long[][] addX = new long[64][64];
    long best = Long.MAX_VALUE;
    Scanner sca = new Scanner(System.in);
    char[] cs;
    Map<Long, Long> cache = new HashMap<>();

    void buildComb() {
        int n = 2 * (r + c);
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                if (j == 0) C[i][j] = 1;
                else if (i == 0) C[i][j] = 0;
                else C[i][j] = C[i - 1][j - 1] + C[i - 1][j];
            }
        }
    }

    void buildTerms() {
        int n = 2 * (r + c);
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                prod[i][j] = C[i][r] * C[j][r];
            }
        }
        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                addY[i][j] = (C[i][r] - C[i - 1][r]) * C[j][r];
            }
        }
        for (int i = 0; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                addX[i][j] = C[i][r] * (C[j][r] - C[j - 1][r]);
            }
        }
    }

    void dfs(long x, long y, int v1, int v2) {
        long d = Math.abs(x - y);
        if (best <= 1 || d - prod[v1][v2] >= best) return;
        if (v1 == 0 && v2 == 0) {
            if (d < best) best = d;
            return;
        }
        if (v1 > 0) {
            dfs(x, y + addY[v1][v2], v1 - 1, v2);
        }
        if (v2 > 0) {
            dfs(x + addX[v1][v2], y, v1, v2 - 1);
        }
    }

    long solve(long x, long y, int v1, int v2) {
        long key = x * 10000 + v1 * 100 + v2;
        Long cached = cache.get(key);
        if (cached != null) return cached;
        long ans = 0L;
        long d = Math.abs(x - y);
        if (d - prod[v1][v2] > best) {
            cache.put(key, ans);
            return ans;
        }
        if (v1 == 0 && v2 == 0) return 1L;
        char ch = cs[v1 + v2 - 1];
        if (v1 > 0 && ch != 'B') {
            ans += solve(x, y + addY[v1][v2], v1 - 1, v2);
        }
        if (v2 > 0 && ch != 'A') {
            ans += solve(x + addX[v1][v2], y, v1, v2 - 1);
        }
        cache.put(key, ans);
        return ans;
    }

    void run() {
        r = sca.nextInt();
        c = sca.nextInt();
        sca.nextLine();
        cs = sca.nextLine().toCharArray();
        buildComb();
        buildTerms();
        int v1 = r + c, v2 = r + c;
        long x = 0, y = 0;
        while (v1 > 0 && v2 > 0) {
            if (x > y) {
                y += addY[v1][v2];
                v1--;
            } else {
                x += addX[v1][v2];
                v2--;
            }
        }
        best = Math.abs(x - y);
        dfs(0, 0, r + c, r + c);
        System.out.println(solve(0, 0, r + c, r + c));
    }

    public static void main(String[] args) {
        new Test().run();
    }
}
